// The second half of the extended journey builds toward an evidence-based release monitor.
const foundations={18:['Probabilities','Independent evaluation'],19:['Dot products','Exponential and logarithm functions'],20:['Calibration','Evaluation and data pipelines']};
const code=q=>({type:'code',minutes:18,xp:470+(q.chapter-15)*35,coins:180+(q.chapter-15)*15,buildsOn:foundations[q.chapter],...q});
const quiz=q=>({type:'quiz',minutes:10,xp:430+(q.chapter-15)*35,coins:165+(q.chapter-15)*15,buildsOn:foundations[q.chapter],...q});
const check=(fn,body)=>`f=scope.get("${fn}")\nassert callable(f), "Define ${fn}."\n${body}`;
const percentileHelper='def percentile(ordered, fraction):\n    position = (len(ordered) - 1) * fraction\n    low = int(position)\n    high = min(low + 1, len(ordered) - 1)\n    return ordered[low] + (ordered[high] - ordered[low]) * (position - low)\n';
const softmaxHelper='import math\n\ndef softmax(logits):\n    if not logits:\n        return []\n    peak = max(logits)\n    weights = [math.exp(x - peak) for x in logits]\n    total = sum(weights)\n    return [w / total for w in weights]\n';
const monitorHelpers='def category_drift(reference, current):\n    if not reference or not current:\n        raise ValueError("Both samples must be nonempty")\n    before, after = {}, {}\n    for item in reference:\n        before[item] = before.get(item, 0) + 1\n    for item in current:\n        after[item] = after.get(item, 0) + 1\n    return 0.5 * sum(abs(before.get(k, 0)/len(reference) - after.get(k, 0)/len(current))\n                     for k in before.keys() | after.keys())\n\ndef selective_metrics(probabilities, labels, minimum):\n    accepted = wrong = 0\n    for p, y in zip(probabilities, labels):\n        if max(p, 1-p) >= minimum:\n            accepted += 1\n            wrong += int(p >= 0.5) != y\n    return {"coverage": accepted/len(labels),\n            "error": wrong/accepted if accepted else None}\n';

export const laterFrontierQuests=[
code({id:'brier-weather',chapter:18,title:'Promises in the mist',subtitle:'Score probabilities with the Brier score',
lesson:['The mist garden records a forecast p for rain and an eventual outcome y: 1 for rain, 0 for no rain. A probability score judges the forecast before it is turned into a yes/no decision.', 'For a binary event, the Brier score is the average of (p - y) squared. A correct, confident forecast scores near 0; a confident mistake scores near 1. Lower is better. A forecast of 0.5 scores 0.25 for either outcome.', 'The score reflects more than calibration. Calibration asks whether events forecast at about 70% happen about 70% of the time. A lower overall Brier score alone does not prove better calibration. Use held-out outcomes and examine reliability too.'],
example:'# Forecasts [0.1, 0.6], outcomes [0, 1]\n# Squared errors: 0.01 and 0.16\n# Brier score: (0.01 + 0.16) / 2 = 0.085',
task:'Write brier_score(probabilities, outcomes) for matching, nonempty lists of probabilities in [0, 1] and binary outcomes. Return the mean squared probability error. Do not threshold the probabilities into labels.',
starter:'def brier_score(probabilities, outcomes):\n    return 0.0',
solution:'def brier_score(probabilities, outcomes):\n    return sum((p-y)**2 for p,y in zip(probabilities, outcomes)) / len(outcomes)',
checks:check('brier_score','for p,y,want in [([0.2,0.8],[0,1],0.04),([0,1],[1,0],1),([0.5],[1],0.25),([0,0.5,1],[0,0,1],1/12)]:\n    assert abs(f(p,y)-want)<1e-10, "Score probabilities, then average over all outcomes."'),
hint:'Pair each forecast with its outcome, square their difference, sum, and divide by the number of observations.',takeaway:'Probability quality is richer than the number of correct yes/no decisions.'}),
code({id:'reliability-bins',chapter:18,title:'The greenhouse promise board',subtitle:'Build a reliability table',
lesson:['Group similar forecast probabilities into bins. Within each bin, compare the average predicted probability with the fraction of outcomes that were positive. These pairs form a reliability diagram.', 'For two equal-width bins, the ranges are [0, 0.5) and [0.5, 1]. The final bin includes exactly 1. An empty bin has no evidence: its averages should be None, not zero.', 'A bin with two examples is much less convincing than one with two hundred. Keep counts beside averages. Binning can hide variation, and results depend on the bin boundaries; a reliability table is evidence to inspect, not a certificate.'],
example:'# Probabilities [0.1, 0.3], outcomes [0, 1], in one bin:\n# count = 2, predicted = 0.2, observed = 0.5\n# This tiny group received more rain than its average forecast.',
task:'Write reliability(probabilities, outcomes, bins). Return one dictionary per equal-width bin, in order, with count, predicted (mean probability) and observed (mean outcome). Empty bins use None for both means. Use min(int(p*bins), bins-1) for the bin index. Inputs match and may be empty; bins is an integer and must be positive, otherwise raise ValueError.',
starter:'def reliability(probabilities, outcomes, bins):\n    return []',
solution:'def reliability(probabilities, outcomes, bins):\n    if bins <= 0:\n        raise ValueError("Positive bin count required")\n    counts = [0]*bins\n    predicted = [0.0]*bins\n    observed = [0.0]*bins\n    for p,y in zip(probabilities, outcomes):\n        i = min(int(p*bins), bins-1)\n        counts[i] += 1\n        predicted[i] += p\n        observed[i] += y\n    return [{"count": n, "predicted": predicted[i]/n if n else None,\n             "observed": observed[i]/n if n else None}\n            for i,n in enumerate(counts)]',
checks:check('reliability','r=f([0,0.4,0.5,1],[0,1,0,1],2)\nassert len(r)==2\nfor got,n,p,y in zip(r,[2,2],[0.2,0.75],[0.5,0.5]):\n    assert got["count"]==n and abs(got["predicted"]-p)<1e-10 and abs(got["observed"]-y)<1e-10\nassert f([],[],2)==[{"count":0,"predicted":None,"observed":None}]*2\nr=f([1],[0],3)\nassert len(r)==3 and r[0]["count"]==0 and r[1]["predicted"] is None\nassert r[2]=={"count":1,"predicted":1,"observed":0}, "Keep p=1 in the last bin."\nfor n in [0,-2]:\n    try: f([],[],n)\n    except ValueError: pass\n    else: raise AssertionError("Reject nonpositive bin counts.")'),
hint:'Keep three arrays: counts, probability totals, and outcome totals. Divide only where the count is nonzero.',takeaway:'Calibration compares probabilities with frequencies, while counts show how much evidence supports each comparison.'}),
code({id:'bootstrap-interval',chapter:18,title:'A basket of possible harvests',subtitle:'Bootstrap an interval for a sample mean',minutes:22,
lesson:['The gardeners have one sample of harvest weights. A bootstrap resample draws from those observed values WITH replacement, using the same number of values as the original sample. Calculate its mean, then repeat.', 'The middle 90% of these resampled means gives a simple percentile bootstrap interval: the 5th and 95th percentiles. The supplied helper interpolates between ordered values. This is an approximate method, especially fragile with tiny or unrepresentative samples.', 'Use random.Random(seed) for a local random generator. Repeating the seed makes the exercise reproducible without changing the game’s global random state. More resamples reduce simulation noise; they do not create new field observations.'],
example:'import random\nrng = random.Random(7)\nvalues = [2, 5, 8]\nresample = [rng.choice(values) for _ in values]\n# Repeated values are allowed; every resample has length 3.\nprint(sum(resample) / len(resample))',
task:'Write bootstrap_interval(values, resamples, seed). For each resample, draw len(values) times using a local random.Random(seed).choice(values), record the mean, then sort the means. Return their interpolated 5th and 95th percentiles as a tuple, using the supplied percentile helper. Raise ValueError for empty values or resamples <= 0. resamples is an integer. Preserve values and global random state.',
starter:'import random\n\n'+percentileHelper+'\ndef bootstrap_interval(values, resamples, seed):\n    return (0.0, 0.0)',
solution:'import random\n\n'+percentileHelper+'\ndef bootstrap_interval(values, resamples, seed):\n    if not values or resamples <= 0:\n        raise ValueError("Need observations and resamples")\n    rng = random.Random(seed)\n    means = []\n    for _ in range(resamples):\n        sample = [rng.choice(values) for _ in values]\n        means.append(sum(sample)/len(sample))\n    means.sort()\n    return percentile(means, 0.05), percentile(means, 0.95)',
checks:check('bootstrap_interval','import random\ndef reference(values,n,seed):\n    rng=random.Random(seed)\n    means=sorted(sum(rng.choice(values) for _ in values)/len(values) for _ in range(n))\n    def pct(q):\n        pos=(n-1)*q; lo=int(pos); hi=min(lo+1,n-1)\n        return means[lo]+(means[hi]-means[lo])*(pos-lo)\n    return pct(0.05),pct(0.95)\nfor values,n,seed in [([1,4,9],31,9),([5,5,5],20,3),([0,0,0,20],40,12),([-3,2,8],1,4)]:\n    original=values.copy(); state=random.getstate()\n    got=f(values,n,seed); want=reference(values,n,seed)\n    assert isinstance(got,tuple) and len(got)==2\n    assert all(abs(a-b)<1e-10 for a,b in zip(got,want)), "Resample with replacement, then take percentiles of the means."\n    assert values==original and random.getstate()==state, "Use a local random generator."\nfor values,n in [([],20),([1],0),([1],-1)]:\n    try: f(values,n,1)\n    except ValueError: pass\n    else: raise AssertionError("Reject empty samples or nonpositive resamples.")'),
hint:'Generate all draws with one local rng, in resample order. Sort the list of means before calling percentile.',takeaway:'Resampling estimates sampling variability; it cannot recover information missing from the original sample.'}),
quiz({id:'interval-meaning',chapter:18,title:'What the mist still hides',subtitle:'Separate simulation noise from sampling bias',
lesson:['A confidence-interval procedure aims to cover a fixed population quantity in a stated proportion of repeated samples under its assumptions. A 90% confidence interval is not a range containing 90% of individual harvests.', 'A percentile bootstrap interval estimates uncertainty from the observed sample. Its coverage is approximate. If gardeners recorded only sunny-day harvests, resampling those rows cannot supply the missing rainy days.', 'More bootstrap repetitions stabilize the computed endpoints. Better collection, suitable methods, and enough representative observations address deeper uncertainty. A random seed makes results repeatable, not correct.'],
task:'Elio bootstraps only sunny-day harvests a million times. What does the extra computation actually help with?',options:['It removes the sunny-day selection bias.','It guarantees exactly 90% coverage for this sample.','It reduces resampling simulation noise, but the missing rainy-day evidence remains missing.','It turns the interval into a prediction range for 90% of individual plants.'],answer:2,
explanations:['Resampling cannot invent observations from a group never collected.','Bootstrap coverage is approximate and depends on assumptions and data.','Correct. More repetitions stabilize this calculation; they do not repair the sample.','An interval for the mean and a prediction interval for individual outcomes answer different questions.'],hint:'Distinguish repeating a calculation from collecting new evidence.',takeaway:'A narrow or reproducible interval can still rest on unrepresentative data.'}),
code({id:'multiclass-softmax',chapter:19,title:'Three lanterns, one forecast',subtitle:'Stable probabilities for multiple classes',
lesson:['A multiclass model can produce one raw score, or logit, per class. Softmax converts logits z into positive weights exp(z), then divides each weight by their sum. The resulting probabilities sum to one.', 'Large logits can overflow exp. Subtract the largest logit from every logit first. This leaves softmax unchanged because the shared exponential factor cancels, while all exponent arguments become nonpositive.', 'Normalized scores are not automatically well-calibrated probabilities. This function is the forward calculation; learning the logits and evaluating their reliability are separate steps.'],
example:'# logits [1000, 1000] would overflow a naive exponential.\n# Subtract max: [0, 0] -> weights [1, 1] -> [0.5, 0.5].\n# Adding the same number to every logit leaves the result unchanged.',
task:'Write softmax(logits), returning probabilities in the same order. Subtract max(logits) before exponentiating with math.exp. Return [] for empty input. Inputs are finite numbers. Do not mutate logits.',
starter:'import math\n\ndef softmax(logits):\n    return []',solution:softmaxHelper,
checks:check('softmax','import math\nfor z in [[1000,1000],[-1000,-1001],[2,-1,3],[7]]:\n    original=z.copy(); got=f(z)\n    weights=[math.exp(x-max(z)) for x in z]; total=sum(weights)\n    assert len(got)==len(z) and all(abs(a-b/total)<1e-10 for a,b in zip(got,weights))\n    assert abs(sum(got)-1)<1e-10 and z==original\nassert f([])==[]\na=f([2,-1,3]); b=f([1002,999,1003])\nassert all(abs(x-y)<1e-10 for x,y in zip(a,b)), "Softmax is invariant to a shared shift."'),
hint:'Find the maximum once, exponentiate each shifted value, then normalize by the sum of those weights.',takeaway:'Algebraically equivalent formulas can behave very differently with finite-precision numbers.'}),
code({id:'multiclass-loss',chapter:19,title:'The cost of the wrong lantern',subtitle:'Cross-entropy through log-sum-exp',
lesson:['For one example whose correct class is target, multiclass cross-entropy is -log(probability of target). Confident wrong predictions should receive a large loss.', 'Even stable softmax can underflow a very tiny probability to zero. Taking its logarithm then fails. Instead calculate the loss directly from logits: log(sum(exp(z - m))) + (m - z_target), where m is the largest logit.', 'This is the log-sum-exp trick. It preserves a large, meaningful penalty without arbitrary probability clipping. This lesson extends the earlier binary loss to any number of mutually exclusive classes.'],
example:'# logits [1000, -1000], target = 1\n# shifted exponential sum is approximately 1.\n# loss = log(1) + (1000 - (-1000)) = 2000.\n# Do not take log(softmax(logits)[1]): that probability may be 0.',
task:'Write multiclass_loss(logits, target) for one example using the stable formula above. target is an integer class index. Raise ValueError for empty logits or target outside [0, len(logits)). Inputs are finite. Return a scalar without clipping probabilities.',
starter:'import math\n\ndef multiclass_loss(logits, target):\n    return 0.0',
solution:'import math\n\ndef multiclass_loss(logits, target):\n    if not logits or not 0 <= target < len(logits):\n        raise ValueError("Valid target and logits required")\n    peak = max(logits)\n    return math.log(sum(math.exp(x-peak) for x in logits)) + (peak-logits[target])',
checks:check('multiclass_loss','import math\nfor z,t,want in [([0,0],1,math.log(2)),([1000,-1000],1,2000),([-1000,1000],1,0),([7],0,0),([2,2,2],2,math.log(3))]:\n    assert abs(f(z,t)-want)<1e-10, "Calculate loss directly from shifted logits."\nassert abs(f([1,3,2],0)-f([1001,1003,1002],0))<1e-10\nfor z,t in [([],0),([1,2],-1),([1,2],2)]:\n    try: f(z,t)\n    except ValueError: pass\n    else: raise AssertionError("Reject invalid class indices, including negative indices.")'),
hint:'Compute the logarithm of the shifted exponential sum, then add max(logits) - logits[target].',takeaway:'Stable loss calculations preserve information that an intermediate probability may lose.'}),
code({id:'dense-layer',chapter:19,title:'A room of little neurons',subtitle:'Build a dense layer and check its shapes',
lesson:['A dense layer contains several neurons. Here each ROW of weights belongs to one output neuron. Its pre-activation is the dot product of that row with the inputs, plus its bias.', 'ReLU returns max(0, value). It introduces a nonlinearity so stacked layers can represent more than one overall linear transformation. This task performs a forward pass, not training.', 'Check dimensions before computing. Python zip silently stops at the shorter iterable; mismatched shapes could otherwise discard inputs without an error. Different libraries store weight matrices in different orientations, so read the contract.'],
example:'# inputs [2, -1], weight row [1, 2], bias 0.5\n# pre-activation = 2*1 + (-1)*2 + 0.5 = 0.5\n# ReLU output = 0.5',
task:'Write dense_relu(inputs, weights, biases). Each weight row represents one output and must have len(inputs) entries; the number of rows must equal len(biases). Raise ValueError for either mismatch. Return one ReLU output per row. Empty inputs are allowed (outputs then depend on biases); zero output rows return []. Preserve inputs.',
starter:'def dense_relu(inputs, weights, biases):\n    return []',
solution:'def dense_relu(inputs, weights, biases):\n    if len(weights) != len(biases) or any(len(row) != len(inputs) for row in weights):\n        raise ValueError("Incompatible layer shapes")\n    return [max(0, sum(x*w for x,w in zip(inputs,row)) + bias)\n            for row,bias in zip(weights,biases)]',
checks:check('dense_relu','import copy\nx=[2,-1]; w=[[1,0],[0,1],[-1,-2]]; b=[0,2,1]\noriginal=copy.deepcopy((x,w,b))\nassert f(x,w,b)==[2,1,1] and (x,w,b)==original\nassert f([-2],[[3],[1]],[1,4])==[0,2]\nassert f([], [[],[]], [-1,2])==[0,2]\nassert f([1,2],[],[])==[]\nfor x,w,b in [([1],[[1,2]],[0]),([1,2],[[1]],[0]),([1],[[1]],[]),([1],[],[0])]:\n    try: f(x,w,b)\n    except ValueError: pass\n    else: raise AssertionError("Check both row widths and bias count before zip.")'),
hint:'Validate every row and the bias count first. Then calculate each dot product, add that row’s bias, and apply max(0, ...).',takeaway:'A neural layer is a collection of arithmetic operations with an explicit shape contract.'}),
code({id:'attention-head',chapter:19,title:'Which lantern should listen?',subtitle:'One scaled dot-product attention head',minutes:24,
lesson:['Attention lets a query select information from a collection. Compare the query with each key using a dot product. Divide the scores by sqrt(d), where d is the query/key dimension, then apply softmax.', 'Use those normalized weights to combine the VALUES, not the keys. Values may have a different dimension from queries and keys. A zero query gives equal scores, so it returns the average value vector.', 'Real transformer layers learn projections and use multiple heads, among other components. This small forward calculation exposes one mechanism. Attention weights are not proof of truth or a complete explanation of a model’s decision.'],
example:'# query [0, 0], keys [[1, 0], [0, 1]]\n# scores [0, 0] -> attention weights [0.5, 0.5]\n# values [[2, 4, 6], [6, 8, 10]] -> output [4, 6, 8]\n# Output width follows values, not query width.',
task:'Write attend(query, keys, values) using the supplied stable softmax. Score each key with dot(query, key)/sqrt(len(query)), normalize, and return the weighted value vector. Shapes are valid and nonempty; keys and values have the same row count. Query and keys share a dimension; all value rows share a possibly different dimension. Preserve all inputs.',
starter:softmaxHelper+'\ndef attend(query, keys, values):\n    return []',
solution:softmaxHelper+'\ndef attend(query, keys, values):\n    scale = math.sqrt(len(query))\n    scores = [sum(q*k for q,k in zip(query,key))/scale for key in keys]\n    weights = softmax(scores)\n    return [sum(w*value[j] for w,value in zip(weights,values))\n            for j in range(len(values[0]))]',
checks:check('attend','import math, copy\nq=[0,0]; k=[[1,0],[0,1]]; v=[[2,4,6],[6,8,10]]\noriginal=copy.deepcopy((q,k,v))\nassert f(q,k,v)==[4,6,8] and (q,k,v)==original\ngot=f([2,0],[[1,0],[0,1]],[[10],[0]])\nassert len(got)==1 and abs(got[0]-10/(1+math.exp(-math.sqrt(2))))<1e-10, "Scale scores by sqrt(key dimension)."\nassert f([1000],[[1],[-1]],[[7,8],[2,3]])==[7,8], "Use numerically stable softmax."\nassert f([3,4],[[1,2]],[[9,8,7]])==[9,8,7], "Combine values, not keys."'),
hint:'Compute one score and weight per key. For each output coordinate, sum weight * value[coordinate] over all rows.',takeaway:'Attention performs a query-dependent weighted combination of information.'}),
code({id:'category-drift',chapter:20,title:'New boats at the beacon',subtitle:'Measure a change in input distributions',
lesson:['The beacon’s forecasts were tested on one mix of delivery types. A new ferry changes that mix. Input drift means the current input distribution differs from a reference distribution; it does not by itself prove worse predictions.', 'For categorical data, total variation distance is half the sum of absolute differences between category frequencies. Include categories found in EITHER sample. It ranges from 0 (same empirical proportions) to 1 (disjoint categories).', 'Normalize each sample by its own size. Samples can differ in length, and finite samples fluctuate. Separately, the relationship between inputs and outcomes can change even if these input proportions look stable. A drift alert invites investigation, not automatic retraining.'],
example:'# Reference: 3 bread, 1 book -> [0.75, 0.25]\n# Current: 1 bread, 1 book -> [0.5, 0.5]\n# Distance = 0.5 * (abs(0.75-0.5) + abs(0.25-0.5)) = 0.25',
task:'Write category_drift(reference, current), returning total variation distance between their empirical category distributions. Count hashable categories across the union of both samples, normalize each by its own length, and raise ValueError if either sample is empty.',
starter:'def category_drift(reference, current):\n    return 0.0',
solution:monitorHelpers.split('\n\ndef selective_metrics')[0],
checks:check('category_drift','for a,b,want in [(["a","a","b"],["b","c"],2/3),(["a"],["b"],1),(["a","b"],["a","a","b","b"],0),([0,0,1],[0,1,1],1/3),([False],[False],0)]:\n    assert abs(f(a,b)-want)<1e-10, "Normalize both samples and include previously unseen categories."\nfor a,b in [([],[]),([],[1]),([1],[])]:\n    try: f(a,b)\n    except ValueError: pass\n    else: raise AssertionError("An empty sample has no empirical distribution.")'),
hint:'Build two count dictionaries. For every key in before.keys() | after.keys(), compare normalized counts, with 0 for missing categories.',takeaway:'Distribution change is a measurable signal whose practical meaning still needs investigation.'}),
code({id:'selective-prediction',chapter:20,title:'Knowing when to ask a neighbour',subtitle:'Coverage and error when a model abstains',
lesson:['A model may abstain on uncertain cases and ask a person to decide. For binary probability p, predicted confidence is max(p, 1-p). Accept only confidence >= the chosen minimum; a negative prediction can be just as confident as a positive one.', 'Coverage is accepted cases divided by all cases. Selective error is mistakes divided by accepted cases. Raising the confidence requirement can reduce coverage; it does not guarantee lower error when the model is unreliable.', 'If nothing is accepted, error is unknown (None), not zero. Report both metrics and inspect who gets excluded. Labels here are eventual evaluation outcomes; they are never available to choose the original prediction.'],
example:'# p=0.1 -> negative label, confidence 0.9\n# p=0.6 -> positive label, confidence 0.6\n# At minimum 0.8 only the first prediction is accepted.\n# If its true label is 1: coverage = 0.5, selective error = 1.0.',
task:'Write selective_metrics(probabilities, labels, minimum) returning {"coverage": ..., "error": ...}. Predict 1 for p >= 0.5, otherwise 0; accept when max(p,1-p) >= minimum. Error is the fraction of accepted predictions that are wrong, or None if no prediction is accepted. Matching lists are nonempty, labels are binary, probabilities are in [0,1], and minimum is in [0.5,1].',
starter:'def selective_metrics(probabilities, labels, minimum):\n    return {"coverage": 0.0, "error": None}',
solution:monitorHelpers.slice(monitorHelpers.indexOf('def selective_metrics')),
checks:check('selective_metrics','cases=[([0.1,0.6],[1,1],0.8,0.5,1),([0.5],[1],0.5,1,0),([0.5],[0],0.9,0,None),([0,1,0.5],[0,0,1],1,2/3,0.5),([0.2,0.8],[0,1],0.8,1,0)]\nfor p,y,t,c,e in cases:\n    got=f(p,y,t)\n    assert abs(got["coverage"]-c)<1e-10, "Count confident negative predictions too; include the threshold boundary."\n    assert got["error"] is None if e is None else abs(got["error"]-e)<1e-10, "Use accepted cases as the error denominator; no accepted cases means None."'),
hint:'Count accepted cases and their mistakes separately. Coverage uses the total sample size; error uses only the accepted count.',takeaway:'Abstention must be evaluated together with how often—and for whom—the model still provides a decision.'}),
quiz({id:'shadow-launch',chapter:20,title:'Let the new lantern watch first',subtitle:'Shadow evaluation and reversible releases',
lesson:['A shadow model receives the same inputs as the active model, but its outputs do not control the real decisions. Store its version, predictions and processing failures, then compare against outcomes when they arrive.', 'A canary release is different: it serves some real traffic. Both need deliberate evaluation; neither guarantees safety. Monitor latency and failures as well as model metrics, and preserve a rollback path to a known version with compatible preprocessing.', 'A version should identify the model and the preprocessing it depends on. Comparing unversioned logs or using outcomes as prediction inputs makes an apparently reassuring report misleading.'],
task:'Which plan lets the new beacon model gather evidence before its predictions affect delivery decisions?',options:['Replace every active prediction immediately and keep no old version.','Run it in shadow, log versioned predictions and failures, and compare with later outcomes while the existing system remains in charge.','Call it a shadow test but let its output choose half the routes.','Train on the arriving outcome before recording the prediction it would have made.'],answer:1,
explanations:['This removes the observation period and a straightforward rollback option.','Correct. Shadow outputs are recorded for evaluation without controlling the live decision.','Serving a fraction of real decisions is a canary-style release, not shadow-only evaluation.','That leaks future information into the prediction and invalidates the comparison.'],hint:'A shadow can observe a decision without making it.',takeaway:'A release plan connects model evidence with operational behavior and a way to recover.'}),
code({id:'beacon-monitor',chapter:20,title:'The keeper’s evening report',subtitle:'Capstone: a versioned monitor with reasons for review',minutes:24,xp:800,coins:320,
lesson:['The beacon keeper wants a short, inspectable report—not an automatic declaration that a model is safe. Combine your input-drift distance with coverage and selective error, retaining the version that produced the forecasts.', 'Each limit is a review rule. Flag drift strictly ABOVE its limit, coverage strictly BELOW its minimum, and accepted error strictly ABOVE its maximum. Equality is allowed. If no case was accepted, record missing evidence instead of inventing a perfect error score.', 'Keep all applicable reasons in a predictable order so a neighbour can understand them. A report with no flags only means these checks passed on this sample. It does not approve deployment, change predictions, or retrain the model.'],
example:'# A report can carry several reasons at once:\n# {"version": "beacon-v2", "drift": 0.4, "coverage": 0.5,\n#  "error": 0.25, "review": True,\n#  "reasons": ["input drift", "low coverage", "accepted errors"]}\n# The keeper can trace the evidence and decide what to investigate.',
task:'Write monitor_release(version, reference, current, probabilities, labels, confidence, drift_limit, min_coverage, max_error). Call the supplied category_drift and selective_metrics helpers. Return version, drift, coverage, error, review (bool), and reasons (list). Append reasons in this order: "input drift" if drift > drift_limit; "low coverage" if coverage < min_coverage; then "no accepted cases" if error is None, otherwise "accepted errors" if error > max_error. review is True exactly when reasons is nonempty. Inputs satisfy the helper contracts; preserve them.',
starter:monitorHelpers+'\ndef monitor_release(version, reference, current, probabilities, labels, confidence, drift_limit, min_coverage, max_error):\n    return {}',
solution:monitorHelpers+'\ndef monitor_release(version, reference, current, probabilities, labels, confidence, drift_limit, min_coverage, max_error):\n    drift = category_drift(reference, current)\n    metrics = selective_metrics(probabilities, labels, confidence)\n    reasons = []\n    if drift > drift_limit:\n        reasons.append("input drift")\n    if metrics["coverage"] < min_coverage:\n        reasons.append("low coverage")\n    if metrics["error"] is None:\n        reasons.append("no accepted cases")\n    elif metrics["error"] > max_error:\n        reasons.append("accepted errors")\n    return {"version": version, "drift": drift, **metrics,\n            "review": bool(reasons), "reasons": reasons}',
checks:check('monitor_release','import copy\nargs=["v2",["bread"],["book"],[0.9,0.5],[0,1],0.8,0.2,0.8,0.1]\noriginal=copy.deepcopy(args)\nr=f(*args)\nassert r=={"version":"v2","drift":1,"coverage":0.5,"error":1,"review":True,"reasons":["input drift","low coverage","accepted errors"]}\nassert args==original\nr=f("v3",[0],[0],[0.5],[1],0.9,0,0.5,0)\nassert r=={"version":"v3","drift":0,"coverage":0,"error":None,"review":True,"reasons":["low coverage","no accepted cases"]}\nr=f("v4",[0],[1],[0,1],[0,0],1,1,1,0.5)\nassert r=={"version":"v4","drift":1,"coverage":1,"error":0.5,"review":False,"reasons":[]}, "Equality at the three limits is allowed."\ncalls=[]\ndef drift_spy(a,b):\n    calls.append("drift"); return 0.3\ndef metrics_spy(p,y,c):\n    calls.append("metrics"); return {"coverage":0.6,"error":0.2}\nold_d,old_m=scope["category_drift"],scope["selective_metrics"]\ntry:\n    scope["category_drift"],scope["selective_metrics"]=drift_spy,metrics_spy\n    r=f("v5",[0],[0],[0],[0],0.8,0.2,0.8,0.1)\n    assert calls==["drift","metrics"] and r["reasons"]==["input drift","low coverage","accepted errors"], "Compose the supplied helpers."\nfinally:\n    scope["category_drift"],scope["selective_metrics"]=old_d,old_m'),
hint:'Calculate the two helper results first. Accumulate every applicable reason rather than returning after the first problem. Use error is None before comparing it with a number.',takeaway:'Reliable ML connects versioned predictions, changing data, evaluation evidence, and human review.'})
];
